            .map(function(l) { return l.trim(); })
            .filter(function(l) {
                return l.indexOf('github.com') !== -1 ||
                    l.indexOf('gitlab') !== -1 ||
                    l.indexOf('gitlab.example.com') !== -1 ||
                    l.indexOf('dev.azure.com') !== -1 ||
                    l.indexOf('ssh.dev.azure.com') !== -1;
