    cli_execute_command({ command: 'git config user.email "' + config.git.authorEmail + '"' });

    try {
        cli_execute_command({ command: 'git fetch origin ' + baseBranch });
    } catch (e) {
        console.warn('Could not fetch origin/' + baseBranch + ':', e);
    }

