        getDiffText: function(prId) {
            try {
                return gitlab_get_mr_diff_text({ workspace: workspace, repository: repository, pullRequestId: String(prId) });
            } catch (e) {
                console.warn('getDiffText (gitlab) failed:', e && e.toString ? e.toString() : String(e));
                return null;
            }
