    const result = passed ? 'fix' : 'update';
    const reworkCommitMsg = configLoader.formatTemplate(config.formats.commitMessage.testRework, {ticketKey: ticketKey, result: result});
    cli_execute_command({
        command: 'git commit -m "' + reworkCommitMsg.replace(/"/g, '\\"') + '"'
