        }
    }

    stillUnmerged = cleanCommandOutput(
        cli_execute_command({ command: 'git diff --name-only --diff-filter=U' }) || ''
    ).trim();
    if (stillUnmerged) {
        throw new Error('Unable to resolve merge conflicts: ' + stillUnmerged);
