            ado_get_pr: function (args) { calls.push(args); return '{"id":42,"title":"T"}'; }
        });
        assert.deepEqual(scm.getPr(42), { id: 42, title: 'T' });
        assert.deepEqual(calls, [{ repository: 'my-repo', pullRequestId: '42' }]);
