    test('getPrDiff falls back to the legacy tool and unwraps a JSON envelope', function () {
        var scm = makeGithub({
            github_get_pr_diff_text: function () { return 'not a diff'; },
            github_get_pr_diff: function () { return JSON.stringify({ result: DIFF }); },
