    // ── getRemoteRepoInfo ─────────────────────────────────────────────────

    test('getRemoteRepoInfo parses a github.com remote URL', function () {
        var scm = makeGithub({
            cli_execute_command: function (args) {
                assert.equal(args.command, 'git config --get remote.origin.url');
                return 'git@github.com:myorg/myrepo.git\n';
