    });

    test('listReviews unwraps JSON-string, envelope and array shapes', function () {
        var scm = makeGithub({
            github_list_pr_reviews: function () { return '[{"id":1}]'; }
        });
        assert.deepEqual(scm.listReviews(5), [{ id: 1 }]);
