    if (opts.path) node.path = opts.path;
    if (opts.line !== undefined) node.line = opts.line;
    return node;
}

function gqlEnvelope(nodes) {
    return JSON.stringify({
        data: { repository: { pullRequest: { reviewThreads: { nodes: nodes } } } }
    });
