function renderReplyLine(reply) {
    var rAuthor = reply.user ? reply.user.login : 'unknown';
    var rDate = reply.created_at ? reply.created_at.substring(0, 10) : '';
    return '> **' + rAuthor + '** (' + rDate + '): ' + String(reply.body || '').trim() + '\n\n';
