    // ── trivial pass-throughs ──────────────────────────────────────────────

    test('listPrs passes workspace, repository and state through', function () {
        var calls = [];
        var scm = makeGithub({
            github_list_prs: function (args) { calls.push(args); return [{ id: 1 }]; }
        });
        var prs = scm.listPrs('open');
