            { cmd: 'git diff --name-only --diff-filter=U', out: '' },
            { cmd: 'git diff --name-only --diff-filter=U', out: '' }
        ]);
        loadStageModule(cli).stageUnmergedPaths(STAGE_CONFIG);
        assert.ok(cli.exhausted(), 'script must be consumed exactly: ' + JSON.stringify(cli.calls));
