    console.log('GitLab MR diff MCP returned no usable diff; falling back to local git diff');
    var localDiff = _gitlabMrDiffLocalFallback(workspace, repository, prIdStr, workingDir, getPr);
    if (_isUsableDiff(localDiff)) {
        return localDiff;
    }

    return raw || '';
