    if (!sha) return null;
    try {
        var raw = gitlab_get_commit_statuses({ workspace: workspace, repository: repository, commitSha: sha });
        var statuses = _toArray(raw);
        if (!statuses.length) return null;
        return statuses.map(_normalizeGitLabCommitStatus);
    } catch (e) {
