    var raw = gitlab_list_mrs({ workspace: workspace, repository: repository, state: requestedState });
    var prs = _toArray(raw).map(_normalizeGitLabMr);
    if (state === 'closed') {
        return prs.filter(function(pr) { return pr.state === 'closed' || pr.merged_at; });
    }
